from pathlib import Path
from html.parser import HTMLParser
class Reader(HTMLParser):
 def __init__(self):
  super().__init__();self.main=False;self.nav=False;self.depth=0;self.links=[];self.ids=set()
 def handle_starttag(self,t,a):
  d=dict(a)
  if t=='main':self.main=True
  if 'id' in d:self.ids.add(d['id'])
  if t=='a' and 'href' in d and self.main:self.links.append(d['href'])
 def handle_endtag(self,t):
  if t=='main':self.main=False
pages={}
for name in ['fields-geometry-transduction','physical-disturbance-paths','extraction-integration-rejection']:
 p=Path('rendered')/(name+'.html');r=Reader();r.feed(p.read_text());pages[p.name]=r
for name,r in pages.items():
 print(name,'main links:',r.links)
 for href in r.links:
  target,sep,frag=href.partition('#')
  if sep and (not target or target in pages):
   other=r if not target else pages[target]
   if frag not in other.ids:print('MISSING FRAGMENT',href)
 text=(Path('rendered')/name).read_text()
 for line in text.splitlines():
  if 'nav-page-text' in line:print('NAV:',line.strip())
